class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);enableEdgeToEdge();setContent{MpScanTheme{HomeRoot()}}}}
private enum class Destination(val label:String,val icon:String){Home("Início","⌂"),Search("Busca","⌕"),Library("Biblioteca","▣"),Profile("Perfil","♙")}

@Composable private fun HomeRoot(){
 var selected by remember{mutableStateOf(Destination.Home)};var selectedWork by remember{mutableStateOf<Work?>(null)};var directReader by remember{mutableStateOf<Pair<Work,Chapter>?>(null)};var works by remember{mutableStateOf<List<Work>>(emptyList())};var loading by remember{mutableStateOf(true)};var error by remember{mutableStateOf("")}
 LaunchedEffect(Unit){runCatching{CatalogRepository().works()}.onSuccess{works=it}.onFailure{error="Não foi possível carregar o catálogo."};loading=false}
 Scaffold(containerColor=MpBackground,bottomBar={if(selectedWork==null&&directReader==null)NavigationBar(containerColor=MpSurface){Destination.entries.forEach{x->NavigationBarItem(selected=selected==x,onClick={selected=x},icon={Text(x.icon)},label={Text(x.label)})}}}){p->
  Box(Modifier.fillMaxSize().padding(p)){when{directReader!=null->Reader(directReader!!.first,directReader!!.second){directReader=null};selectedWork!=null->WorkDetails(selectedWork!!,{selectedWork=null});selected==Destination.Library->OfflineLibrary{w,c->directReader=w to c};loading->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()};error.isNotBlank()->Message(error);works.isEmpty()->Message("As obras publicadas aparecerão aqui.");selected==Destination.Home->Home(works,Modifier,{selectedWork=it});selected==Destination.Search->Search(works){selectedWork=it};else->Message("O Perfil será conectado depois da Biblioteca.")}}
 }
}
@Composable private fun OfflineLibrary(open:(Work,Chapter)->Unit){val context=LocalContext.current;val store=remember{OfflineStore(context.applicationContext)};var downloads by remember{mutableStateOf(store.downloads())};Column(Modifier.fillMaxSize().padding(horizontal=16.dp)){Spacer(Modifier.height(16.dp));Header();Text("Biblioteca",fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineLarge,modifier=Modifier.padding(top=28.dp));Text("Capítulos baixados",color=MpMuted,modifier=Modifier.padding(top=4.dp,bottom=18.dp));if(downloads.isEmpty()){Surface(Modifier.fillMaxWidth(),color=MpSurface,shape=RoundedCornerShape(22.dp),border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Column(Modifier.padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("▣",color=MpAccent,style=MaterialTheme.typography.displaySmall);Text("Nenhum capítulo baixado",fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=12.dp));Text("Abra uma obra e toque em Baixar dentro do capítulo.",color=MpMuted)}}}else LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(bottom=24.dp)){items(downloads,key={it.workId+it.chapterId}){item->DownloadedRow(item,{open(item.toWork(),item.toChapter())}){store.delete(item.workId,item.chapterId);downloads=store.downloads()}}}}}
@Composable private fun DownloadedRow(item:OfflineChapter,open:()->Unit,delete:()->Unit){Surface(Modifier.fillMaxWidth(),color=MpSurface,shape=RoundedCornerShape(18.dp),border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(item.workCover,item.workTitle,Modifier.size(58.dp).clip(RoundedCornerShape(12.dp)).background(MpSurface2),contentScale=ContentScale.Crop);Column(Modifier.weight(1f).padding(horizontal=12.dp).clickable{open()}){Text(item.workTitle,fontWeight=FontWeight.Bold,maxLines=1,overflow=TextOverflow.Ellipsis);Text("${item.chapterLabel} • ${item.pageCount} páginas",color=MpMuted,style=MaterialTheme.typography.bodySmall);Text("Disponível offline",color=MpAccent2,style=MaterialTheme.typography.labelSmall)};TextButton(delete){Text("Excluir")}}}}
private fun OfflineChapter.toWork()=Work(workId,workTitle,"",workCover,"","","","",emptyList(),0,0)
private fun OfflineChapter.toChapter()=Chapter(chapterId,chapterLabel.substringAfter("Capítulo ").toDoubleOrNull(),"",true,0)
@Composable private fun Header(){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(48.dp).clip(RoundedCornerShape(16.dp)).background(Brush.linearGradient(listOf(MpAccent,MpAccent2))),contentAlignment=Alignment.Center){Text("MP",fontWeight=FontWeight.Black)};Spacer(Modifier.width(12.dp));Column{Text("MP SCAN",fontWeight=FontWeight.Black,style=MaterialTheme.typography.titleMedium);Text("Sua próxima leitura começa aqui",color=MpMuted,style=MaterialTheme.typography.bodySmall)};Spacer(Modifier.weight(1f));Surface(shape=RoundedCornerShape(14.dp),color=MpSurface,border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Box(Modifier.size(42.dp),contentAlignment=Alignment.Center){Text("♢")}}}}
@Composable private fun Home(works:List<Work>,modifier:Modifier,open:(Work)->Unit){LazyColumn(modifier.fillMaxSize().padding(horizontal=16.dp),contentPadding=PaddingValues(top=16.dp,bottom=32.dp),verticalArrangement=Arrangement.spacedBy(28.dp)){item{Header()};item{Hero(works.first(),open)};item{Rail("Em alta",works.sortedByDescending{it.reads}.take(10),true,open)};item{Rail("Atualizações recentes",works.take(10),false,open)}}}
@Composable private fun Hero(w:Work,open:(Work)->Unit){Box(Modifier.fillMaxWidth().height(490.dp).clip(RoundedCornerShape(34.dp)).background(MpSurface)){AsyncImage(w.banner.ifBlank{w.cover},w.title,Modifier.fillMaxSize(),contentScale=ContentScale.Crop);Box(Modifier.fillMaxSize().background(Brush.horizontalGradient(listOf(Color(0xF207070A),Color(0xA607070A),Color.Transparent))));Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color.Transparent,Color(0xF507070A)))));Column(Modifier.align(Alignment.BottomStart).padding(26.dp).fillMaxWidth(.92f)){Text("DESTAQUE MP SCAN",color=MpAccent2,fontWeight=FontWeight.Black,style=MaterialTheme.typography.labelSmall);Spacer(Modifier.height(10.dp));Text(w.title,fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineLarge,maxLines=2,overflow=TextOverflow.Ellipsis);Text(w.synopsis,color=MpMuted,maxLines=3,overflow=TextOverflow.Ellipsis,modifier=Modifier.padding(vertical=12.dp));Button(onClick={open(w)},shape=RoundedCornerShape(14.dp)){Text("Ver detalhes",fontWeight=FontWeight.Black)}}}}
@Composable private fun Rail(title:String,works:List<Work>,ranked:Boolean,open:(Work)->Unit){Column{Text(title,fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall);Spacer(Modifier.height(12.dp));LazyRow(horizontalArrangement=Arrangement.spacedBy(13.dp)){items(works,key={it.id}){w->Box{Card(w,open);if(ranked)Text((works.indexOf(w)+1).toString(),fontWeight=FontWeight.Black,style=MaterialTheme.typography.displaySmall,color=Color.White,modifier=Modifier.align(Alignment.BottomStart).background(Color(0xB30B0B0D)).padding(horizontal=8.dp))}}}}}
@Composable private fun Card(w:Work,open:(Work)->Unit){Column(Modifier.width(148.dp).clickable{open(w)}){AsyncImage(w.cover,w.title,Modifier.fillMaxWidth().aspectRatio(3f/4f).clip(RoundedCornerShape(18.dp)).background(MpSurface2),contentScale=ContentScale.Crop);Text(w.title,fontWeight=FontWeight.Bold,maxLines=1,overflow=TextOverflow.Ellipsis,modifier=Modifier.padding(top=8.dp));Text(w.type,color=MpMuted,style=MaterialTheme.typography.bodySmall)}}
@Composable private fun Search(works:List<Work>,open:(Work)->Unit){
 var query by remember{mutableStateOf("")};var status by remember{mutableStateOf("")};var genre by remember{mutableStateOf("")}
 val genres=remember(works){works.flatMap{it.genres}.distinct().sorted()}
 val filtered=remember(works,query,status,genre){works.filter{w->(query.isBlank()||(w.title+" "+w.author+" "+w.genres.joinToString()).contains(query,true))&&(status.isBlank()||w.status.equals(status,true))&&(genre.isBlank()||w.genres.any{it.equals(genre,true)})}}
 Column(Modifier.fillMaxSize().padding(horizontal=16.dp,vertical=14.dp)){Header();Spacer(Modifier.height(18.dp));OutlinedTextField(query,{query=it},Modifier.fillMaxWidth(),singleLine=true,shape=RoundedCornerShape(16.dp),leadingIcon={Text("⌕")},label={Text("Nome, gênero ou autor")});LazyRow(Modifier.padding(vertical=12.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){item{FilterChip(status.isBlank(),{status=""},{Text("Todos")})};items(listOf("Em andamento","Completa","Em pausa","Futura","Cancelada")){s->FilterChip(status==s,{status=if(status==s)"" else s},{Text(s)})}};if(genres.isNotEmpty())LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(genres){g->FilterChip(genre==g,{genre=if(genre==g)"" else g},{Text(g)})}};Text("${filtered.size} obras",color=MpMuted,modifier=Modifier.padding(vertical=10.dp));LazyVerticalGrid(GridCells.Adaptive(140.dp),horizontalArrangement=Arrangement.spacedBy(12.dp),verticalArrangement=Arrangement.spacedBy(18.dp)){gridItems(filtered,key={it.id}){Card(it,open)}}}
}
@Composable private fun WorkDetails(work:Work,back:()->Unit){var chapters by remember(work.id){mutableStateOf<List<Chapter>>(emptyList())};var loading by remember(work.id){mutableStateOf(true)};var reading by remember(work.id){mutableStateOf<Chapter?>(null)};if(reading!=null){Reader(work,reading!!){reading=null};return};LaunchedEffect(work.id){runCatching{CatalogRepository().chapters(work.id)}.onSuccess{chapters=it};loading=false};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=30.dp)){item{Box(Modifier.fillMaxWidth().height(320.dp)){AsyncImage(work.banner.ifBlank{work.cover},work.title,Modifier.fillMaxSize(),contentScale=ContentScale.Crop);Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color(0x55000000),MpBackground))));FilledTonalButton(back,Modifier.padding(16.dp)){Text("←")}}};item{Row(Modifier.padding(horizontal=16.dp)){AsyncImage(work.cover,work.title,Modifier.width(116.dp).aspectRatio(3f/4f).clip(RoundedCornerShape(18.dp)),contentScale=ContentScale.Crop);Column(Modifier.padding(start=16.dp)){Text(work.type.uppercase(),color=MpAccent2,style=MaterialTheme.typography.labelSmall);Text(work.title,fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall);Text(work.status,color=MpMuted,modifier=Modifier.padding(top=8.dp));Text(work.author,color=MpMuted)}}};item{Surface(Modifier.fillMaxWidth().padding(16.dp),color=MpSurface,shape=RoundedCornerShape(18.dp),border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Text(work.synopsis.ifBlank{"Sinopse ainda não informada."},color=MpMuted,modifier=Modifier.padding(16.dp))}};item{Text("Capítulos",fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall,modifier=Modifier.padding(16.dp,8.dp))};if(loading)item{LinearProgressIndicator(Modifier.fillMaxWidth().padding(horizontal=16.dp))};items(chapters,key={it.id}){c->Surface(Modifier.fillMaxWidth().padding(horizontal=16.dp,vertical=5.dp).clickable{reading=c},color=MpSurface,shape=RoundedCornerShape(16.dp),border=androidx.compose.foundation.BorderStroke(1.dp,MpLine)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(48.dp).clip(RoundedCornerShape(14.dp)).background(MpSurface2),contentAlignment=Alignment.Center){Text(c.number?.toString()?.removeSuffix(".0")?:"—",color=MpAccent,fontWeight=FontWeight.Black)};Column(Modifier.padding(start=12.dp)){Text(c.label,fontWeight=FontWeight.Bold);if(c.title.isNotBlank())Text(c.title,color=MpMuted,style=MaterialTheme.typography.bodySmall)}}}}}}
@Composable private fun Reader(work:Work,chapter:Chapter,back:()->Unit){
 val context=LocalContext.current;val store=remember{OfflineStore(context.applicationContext)};val readingStore=remember{ReadingStore(context.applicationContext)};val scope=rememberCoroutineScope();val listState=rememberLazyListState()
 var pages by remember(chapter.id){mutableStateOf<List<String>>(emptyList())};var remotePages by remember(chapter.id){mutableStateOf<List<String>>(emptyList())};var loading by remember(chapter.id){mutableStateOf(true)};var failed by remember(chapter.id){mutableStateOf(false)};var offline by remember(chapter.id){mutableStateOf(false)};var downloading by remember(chapter.id){mutableStateOf(false)};var progress by remember(chapter.id){mutableIntStateOf(0)};var downloadError by remember(chapter.id){mutableStateOf("")}
 LaunchedEffect(chapter.id){val saved=store.localPages(work.id,chapter.id);if(saved.isNotEmpty()){pages=saved;offline=true;loading=false}else{runCatching{CatalogRepository().pages(work.id,chapter.id)}.onSuccess{remotePages=it;pages=it}.onFailure{failed=true};loading=false};if(pages.isNotEmpty()){val last=readingStore.progress(work.id,chapter.id)?.page?.minus(1)?.coerceIn(0,pages.lastIndex)?:0;listState.scrollToItem(last)}}
 LaunchedEffect(listState,pages.size){if(pages.isNotEmpty())snapshotFlow{listState.firstVisibleItemIndex}.distinctUntilChanged().collect{index->readingStore.save(work,chapter,index+1,pages.size)}}
 Column(Modifier.fillMaxSize().background(Color(0xFF050507))){Row(Modifier.fillMaxWidth().background(Color(0xEE0B0B0D)).padding(8.dp),verticalAlignment=Alignment.CenterVertically){FilledTonalButton(back){Text("←")};Column(Modifier.weight(1f).padding(horizontal=12.dp)){Text(work.title,fontWeight=FontWeight.Bold,maxLines=1,overflow=TextOverflow.Ellipsis);Text(if(offline) "${chapter.label} • salvo offline" else chapter.label,color=if(offline)MpAccent2 else MpMuted,style=MaterialTheme.typography.bodySmall)};if(!offline&&pages.isNotEmpty())Button(onClick={scope.launch{downloading=true;downloadError="";runCatching{store.download(work,chapter,remotePages.ifEmpty{pages}){progress=it}}.onSuccess{pages=it;offline=true}.onFailure{downloadError="Não foi possível concluir o download."};downloading=false}},enabled=!downloading,shape=RoundedCornerShape(12.dp)){Text(if(downloading)"$progress%" else "Baixar")}}
  if(downloading)LinearProgressIndicator(progress={progress/100f},Modifier.fillMaxWidth())
  if(downloadError.isNotBlank())Text(downloadError,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(12.dp))
  when{loading->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()};failed->Message("Este capítulo não está salvo e não foi possível conectar.");pages.isEmpty()->Message("Nenhuma página encontrada.");else->LazyColumn(Modifier.fillMaxSize(),state=listState,horizontalAlignment=Alignment.CenterHorizontally){items(pages){page->AsyncImage(page,null,Modifier.fillMaxWidth(),contentScale=ContentScale.FillWidth)}}}
 }
}
@Composable private fun Message(text:String){Box(Modifier.fillMaxSize().padding(24.dp),contentAlignment=Alignment.Center){Text(text,color=MpMuted)}}
